fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> 
where
    T: Clone,
{
    // Requires: The index must be less than or equal to the length of the array
    // Ensures: The resulting vector has a length of one greater than the original array
    //          and contains all elements of the original array with the new value inserted at the specified index.
    // Invariant: At any point in the loop, the length of `result` is equal to the number of elements processed from `arr` plus the number of insertions made.
    // Decreases: The number of iterations left in the loop.
    // The function is total, as it handles all valid inputs according to the requires clause.

    assert!(idx <= arr.len()); // Ensure the index is valid

    let mut result = Vec::with_capacity(arr.len() + 1);
    
    // Loop invariant: At the start of each iteration, `result` contains the first `i` elements of `arr` and the new value has been inserted `inserted` times.
    let mut inserted = 0; // Count of how many times we've inserted the new value
    for (i, item) in arr.iter().enumerate() {
        // At the start of the loop, we have `result.len() == i + inserted`
        // We will ensure that `result.len()` is always `i + inserted` after this iteration
        assert!(result.len() == i + inserted);
        
        if i == idx {
            // Insert the new value at the specified index
            result.push(value.clone());
            inserted += 1; // Increment the insertion count
        }
        // Push the current item from the original array
        result.push(item.clone());
    }
    
    // If the index is equal to the length of the original array, we need to add the new value at the end
    if idx == arr.len() {
        result.push(value);
    }
    
    // Ensure the final result has the correct length
    assert!(result.len() == arr.len() + 1);
    
    result
}